ignores-capacity-change-window.rules.yml:
{
  "groups": [
    {
      "name": "owned_disk_prediction",
      "rules": [
        {
          "record": "opsforge:disk_predicted_avail_bytes:5m",
          "expr": "predict_linear(node_filesystem_avail_bytes{mountpoint=\"/data\"}[5m], 300)"
        },
        {
          "alert": "OwnedDiskWillFill",
          "expr": "(predict_linear(node_filesystem_avail_bytes{mountpoint=\"/data\"}[5m], 300) < 0) and (node_filesystem_avail_bytes{mountpoint=\"/data\"} < 200) and (deriv(node_filesystem_avail_bytes{mountpoint=\"/data\"}[5m]) < 0) and (abs(deriv(node_filesystem_avail_bytes{mountpoint=\"/data\"}[2m]) - deriv(node_filesystem_avail_bytes{mountpoint=\"/data\"}[5m])) <= abs(deriv(node_filesystem_avail_bytes{mountpoint=\"/data\"}[5m])) * 0.1)",
          "for": "2m",
          "labels": {
            "scope": "private",
            "prediction_window": "5m",
            "horizon": "5m"
          },
          "annotations": {
            "assumption": "linear-window heuristic, not a capacity guarantee"
          }
        }
      ]
    }
  ]
}

